export const GAME_STORIES = JSON.parse("{\"story-architect-12-secret\":{\"id\":\"story-architect-12-secret\",\"name\":\"(Cornerstone)\",\"triggers\":[{\"type\":\"distance\",\"cells\":1}],\"frames\":{\"1\":{\"advance\":\"click\",\"duration\":3,\"next\":null,\"attaches\":[],\"boxes\":[{\"id\":\"box-secret\",\"cellOffset\":{\"dx\":0,\"dy\":1.1,\"dz\":0},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":1},\"fill\":{\"color\":\"#f4ecd6\",\"opacity\":1},\"text\":[{\"chars\":\"From a margin of her sketchbook:\\n\",\"style\":{\"font\":\"Permanent Marker\",\"size\":10,\"color\":\"#3a3326\",\"weight\":\"normal\"}},{\"chars\":\"\\\"I wonder if anyone will find this.\\\"\",\"style\":{\"font\":\"Caveat\",\"size\":12,\"color\":\"#2a2418\",\"weight\":\"normal\",\"italic\":true}}],\"buttons\":null,\"buttonsPerRow\":3}]}}},\"story-architect-01-welcome\":{\"id\":\"story-architect-01-welcome\",\"name\":\"Welcome\",\"triggers\":[{\"type\":\"distance\",\"cells\":8}],\"frames\":{\"1\":{\"advance\":\"click\",\"duration\":3,\"next\":\"2\",\"attaches\":[],\"boxes\":[{\"id\":\"box-w1-main\",\"cellOffset\":{\"dx\":0,\"dy\":1.7,\"dz\":-0.4},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"This was Wren's estate.\\nShe was born in 1740. She died here at seventy-one.\\nWhat she built is still standing.\\nWhat she did not finish is still here too.\\nWalk her path.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":14,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3}]},\"2\":{\"advance\":\"click\",\"duration\":3,\"next\":null,\"attaches\":[],\"boxes\":[{\"id\":\"box-w2-main\",\"cellOffset\":{\"dx\":0,\"dy\":1.7,\"dz\":-0.4},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"She began here in this garden.\\nShe ended at the top of a stair she never finished.\\nEverything between is the architecture.\\n\\nHer mother taught her to draw\\nbefore she taught her to read.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":14,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3}]}}},\"story-architect-02-first-sketch\":{\"id\":\"story-architect-02-first-sketch\",\"name\":\"First sketch\",\"triggers\":[{\"type\":\"distance\",\"cells\":6}],\"frames\":{\"1\":{\"advance\":\"click\",\"duration\":3,\"next\":\"2\",\"attaches\":[],\"boxes\":[{\"id\":\"box-bench-main\",\"cellOffset\":{\"dx\":0,\"dy\":1.7,\"dz\":0},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"On this bench, age nineteen,\\nshe drew her first cathedral.\\nShe had never seen one in person.\\nShe copied from engravings in her mother's books.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":14,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3}]},\"2\":{\"advance\":\"click\",\"duration\":3,\"next\":null,\"attaches\":[],\"boxes\":[{\"id\":\"box-bench-2\",\"cellOffset\":{\"dx\":0,\"dy\":1.7,\"dz\":0},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"She kept that sketch all her life.\\nIt is folded in the desk drawer in the study.\\nThe paper has gone brown.\\nThe lines have not.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":14,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3}]}}},\"story-architect-03-pavilion\":{\"id\":\"story-architect-03-pavilion\",\"name\":\"The pavilion\",\"triggers\":[{\"type\":\"distance\",\"cells\":8}],\"frames\":{\"1\":{\"advance\":\"click\",\"duration\":3,\"next\":null,\"attaches\":[],\"boxes\":[{\"id\":\"box-pav-main\",\"cellOffset\":{\"dx\":0,\"dy\":3.4,\"dz\":0},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"Her first build. Twenty-two.\\nFour columns. One roof. No plan.\\nShe built it the year her mother died.\\nThe fourth column she left half-finished.\\nShe never explained why.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":14,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":[{\"label\":\"Walk on\",\"target\":null},{\"label\":\"The mason\",\"target\":\"2\"},{\"label\":\"Look at the column\",\"target\":\"3\"}],\"buttonsPerRow\":3},{\"id\":\"box-pav-thought\",\"cellOffset\":{\"dx\":1.8,\"dy\":2.4,\"dz\":1.2},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":1},\"fill\":{\"color\":\"#f4ecd6\",\"opacity\":1},\"text\":[{\"chars\":\"She wrote to a mason\\nin another country.\\nShe asked how the joints\\nshould meet.\",\"style\":{\"font\":\"Caveat\",\"size\":13,\"color\":\"#3a3326\",\"weight\":\"normal\",\"italic\":true}}],\"buttons\":null,\"buttonsPerRow\":3}]},\"2\":{\"advance\":\"click\",\"duration\":3,\"next\":null,\"attaches\":[],\"boxes\":[{\"id\":\"box-pav-mason\",\"cellOffset\":{\"dx\":0,\"dy\":3.4,\"dz\":0},\"width\":3,\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"His name was Joseph Pelle. He wrote back\\nsix pages. Most was technical.\\n\\nThe last paragraph she lived by:\\n\\n\",\"style\":{\"font\":\"Permanent Marker\",\"size\":13,\"color\":\"#0b0d14\",\"weight\":\"normal\"}},{\"chars\":\"Do not seek instruction.\\nBuild, then look.\\nThe joints will tell you\\nwhat they need.\",\"style\":{\"font\":\"Caveat\",\"size\":16,\"color\":\"#2a2418\",\"weight\":\"normal\",\"italic\":true}},{\"chars\":\"\\n\\nHis letter still hangs above her desk.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":12,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3}]},\"3\":{\"advance\":\"click\",\"duration\":3,\"next\":null,\"attaches\":[],\"boxes\":[{\"id\":\"box-pav-column\",\"cellOffset\":{\"dx\":0,\"dy\":3.4,\"dz\":0},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"The fourth column came down years later.\\nShe was forty-three.\\nShe did not rebuild it.\\n\\nThere is another like it.\\nLook for it at the cathedral altar.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":14,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3}]}}},\"story-architect-04-tostudy\":{\"id\":\"story-architect-04-tostudy\",\"name\":\"To the study\",\"triggers\":[{\"type\":\"distance\",\"cells\":6}],\"frames\":{\"1\":{\"advance\":\"click\",\"duration\":3,\"next\":null,\"attaches\":[],\"boxes\":[{\"id\":\"box-ts-main\",\"cellOffset\":{\"dx\":0,\"dy\":1.7,\"dz\":0},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"Her study is through the door ahead.\\nShe lived in it for nineteen years\\nwithout leaving for more than a day.\\n\\nShe took meals at the small table.\\nShe slept in the loft above.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":14,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3}]}}},\"story-architect-05-desk\":{\"id\":\"story-architect-05-desk\",\"name\":\"At the desk\",\"triggers\":[{\"type\":\"distance\",\"cells\":6}],\"frames\":{\"1\":{\"advance\":\"click\",\"duration\":3,\"next\":\"2\",\"attaches\":[],\"boxes\":[{\"id\":\"box-desk-a\",\"cellOffset\":{\"dx\":0,\"dy\":1.6,\"dz\":-0.5},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"Here she drew the cathedral.\\nEvery night for three years.\\n1778 to 1781.\\nShe began at dusk and stopped at dawn.\\nShe rebuilt this desk three times.\\nThe angle of light from the south\\nwas wrong.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":13,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3},{\"id\":\"box-desk-letter\",\"cellOffset\":{\"dx\":-1.4,\"dy\":2.1,\"dz\":-0.6},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":1},\"fill\":{\"color\":\"#f4ecd6\",\"opacity\":1},\"text\":[{\"chars\":\"Pelle's letter,\\nframed.\\nThe paper has yellowed.\\nThe ink has not.\",\"style\":{\"font\":\"Caveat\",\"size\":13,\"color\":\"#3a3326\",\"weight\":\"normal\",\"italic\":true}}],\"buttons\":null,\"buttonsPerRow\":3}]},\"2\":{\"advance\":\"click\",\"duration\":3,\"next\":null,\"attaches\":[],\"boxes\":[{\"id\":\"box-desk-brigid\",\"cellOffset\":{\"dx\":0,\"dy\":1.6,\"dz\":-0.5},\"width\":2.8,\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"She did not draw alone.\\n\\nFor twelve of those years\\nBrigid sat at this table.\\nShe was a botanical illustrator.\\nShe traced leaves while Wren traced naves.\\n\\nShe died in the winter of 1773.\\nFever. She was thirty-six.\\n\\nThe second column came down\\nthe spring after.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":13,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3}]}}},\"story-architect-06-window\":{\"id\":\"story-architect-06-window\",\"name\":\"At the window\",\"triggers\":[{\"type\":\"distance\",\"cells\":5}],\"frames\":{\"1\":{\"advance\":\"click\",\"duration\":3,\"next\":null,\"attaches\":[],\"boxes\":[{\"id\":\"box-win-main\",\"cellOffset\":{\"dx\":0,\"dy\":1.7,\"dz\":0.6},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"She watched the rain from here\\nfor thirty years.\\n\\nShe drew rain into the stone of the cathedral.\\nIf you visit, look at the columns at noon.\\nThe shadows are diagonal.\\nThat is the rain.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":14,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3}]}}},\"story-architect-07-threshold\":{\"id\":\"story-architect-07-threshold\",\"name\":\"The cathedral\",\"triggers\":[{\"type\":\"distance\",\"cells\":10}],\"frames\":{\"1\":{\"advance\":\"click\",\"duration\":3,\"next\":\"2\",\"attaches\":[],\"boxes\":[{\"id\":\"box-th1\",\"cellOffset\":{\"dx\":0,\"dy\":2.2,\"dz\":0},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2.5},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"Her masterpiece. Finished 1781.\\nShe was forty-one.\\nThe dedication ceremony was\\nthe only public event of her life.\\n\\nShe wore a grey dress.\\nShe did not speak.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":14,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3}]},\"2\":{\"advance\":\"click\",\"duration\":3,\"next\":\"3\",\"attaches\":[],\"boxes\":[{\"id\":\"box-th2\",\"cellOffset\":{\"dx\":0,\"dy\":2.2,\"dz\":0},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2.5},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"She walked the nave once that day.\\nShe wept at the altar.\\nShe did not return\\nfor nineteen years.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":16,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3}]},\"3\":{\"advance\":\"click\",\"duration\":3,\"next\":null,\"attaches\":[],\"boxes\":[{\"id\":\"box-th3\",\"cellOffset\":{\"dx\":0,\"dy\":2.2,\"dz\":0},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2.5},\"fill\":{\"color\":\"#f8eed8\",\"opacity\":1},\"text\":[{\"chars\":\"It stood for one hundred and forty-two years.\\nWeddings. Coronations. One small war.\\nThen the larger war reached her town\\nin the autumn of 1923.\\nIt was shelled for nine hours.\\nThe roof fell first.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":13,\"color\":\"#3a3326\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3}]}}},\"story-architect-08-altar\":{\"id\":\"story-architect-08-altar\",\"name\":\"At the altar\",\"triggers\":[{\"type\":\"distance\",\"cells\":6}],\"frames\":{\"1\":{\"advance\":\"click\",\"duration\":3,\"next\":\"2\",\"attaches\":[],\"boxes\":[{\"id\":\"box-alt-1\",\"cellOffset\":{\"dx\":0,\"dy\":2.4,\"dz\":0},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"The broken column to your left.\\nShe placed it the year she returned, age sixty.\\nShe took it down by hand.\\nShe was alone. It took a week.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":14,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3}]},\"2\":{\"advance\":\"click\",\"duration\":3,\"next\":null,\"attaches\":[],\"boxes\":[{\"id\":\"box-alt-2\",\"cellOffset\":{\"dx\":0,\"dy\":2.4,\"dz\":0},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"Two broken columns. The pavilion and the altar.\\nThe first for her mother.\\nThe second for Brigid.\\n\\nShe never said this to anyone.\\nThe groundskeeper figured it out\\nlong after she was gone.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":14,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3}]}}},\"story-architect-09-toimpossible\":{\"id\":\"story-architect-09-toimpossible\",\"name\":\"To the unfinished\",\"triggers\":[{\"type\":\"distance\",\"cells\":6}],\"frames\":{\"1\":{\"advance\":\"click\",\"duration\":3,\"next\":null,\"attaches\":[],\"boxes\":[{\"id\":\"box-ti\",\"cellOffset\":{\"dx\":0,\"dy\":1.8,\"dz\":0},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"She returned at sixty\\nafter a dream she would not describe.\\n\\nShe began drawing again.\\nShe did not draw cathedrals.\\nShe drew stairs.\\n\\nLook up.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":14,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3}]}}},\"story-architect-10-impossible\":{\"id\":\"story-architect-10-impossible\",\"name\":\"The impossible space\",\"triggers\":[{\"type\":\"distance\",\"cells\":7}],\"frames\":{\"1\":{\"advance\":\"click\",\"duration\":3,\"next\":null,\"attaches\":[],\"boxes\":[{\"id\":\"box-imp-main\",\"cellOffset\":{\"dx\":0,\"dy\":3.4,\"dz\":0},\"width\":\"auto\",\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"Three staircases.\\nThey do not meet the same floor.\\nThe last one ends in air.\\n\\nShe drew them for eleven years.\\nShe built them for nine.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":14,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":[{\"label\":\"Read her note\",\"target\":\"2\"},{\"label\":\"Why?\",\"target\":\"3\"},{\"label\":\"Walk it\",\"target\":null}],\"buttonsPerRow\":3}]},\"2\":{\"advance\":\"click\",\"duration\":3,\"next\":null,\"attaches\":[],\"boxes\":[{\"id\":\"box-imp-note\",\"cellOffset\":{\"dx\":0,\"dy\":3.4,\"dz\":0},\"width\":3.2,\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#f4ecd6\",\"opacity\":1},\"text\":[{\"chars\":\"From the last page of her last sketchbook,\\nundated, in her shaking hand:\\n\\n\",\"style\":{\"font\":\"Permanent Marker\",\"size\":12,\"color\":\"#0b0d14\",\"weight\":\"normal\"}},{\"chars\":\"I have understood it.\\nTime is a stair.\\nWe climb the same step many times\\nbefore we notice it is the same.\\n\\nA building is not a place.\\nIt is a memory you can walk into.\\n\\nI have built a stair to find Brigid.\\nI know it will not work.\\nI build it anyway.\",\"style\":{\"font\":\"Caveat\",\"size\":15,\"color\":\"#2a2418\",\"weight\":\"normal\",\"italic\":true}}],\"buttons\":null,\"buttonsPerRow\":3}]},\"3\":{\"advance\":\"click\",\"duration\":3,\"next\":null,\"attaches\":[],\"boxes\":[{\"id\":\"box-imp-why\",\"cellOffset\":{\"dx\":0,\"dy\":3.4,\"dz\":0},\"width\":3,\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"Visitors at the time said she was losing her mind.\\nThe drawings disagree.\\nEvery angle is exact. Every joint accounted for.\\n\\nThe last stair does not arrive at a landing\\nbecause she did not finish it.\\nShe died two months\\nbefore it would have closed.\",\"style\":{\"font\":\"Permanent Marker\",\"size\":13,\"color\":\"#0b0d14\",\"weight\":\"normal\"}}],\"buttons\":null,\"buttonsPerRow\":3}]}}},\"story-architect-11-end\":{\"id\":\"story-architect-11-end\",\"name\":\"End\",\"triggers\":[{\"type\":\"distance\",\"cells\":5}],\"frames\":{\"1\":{\"advance\":\"click\",\"duration\":3,\"next\":null,\"attaches\":[],\"boxes\":[{\"id\":\"box-end-main\",\"cellOffset\":{\"dx\":0,\"dy\":1.7,\"dz\":0},\"width\":3.2,\"height\":\"auto\",\"anchor\":\"center\",\"border\":{\"shape\":\"rect\",\"stroke\":\"#0b0d14\",\"weight\":2.5},\"fill\":{\"color\":\"#fff4dc\",\"opacity\":1},\"text\":[{\"chars\":\"Wren Halpern.\\n1740 — 1811.\\n\\nShe outlived her mother, her partner, her cathedral.\\nShe never married. She left no will.\\nThe estate went to her gardener, Tomas,\\nwho had drawn for her in the last years\\nwhen her hands began to fail.\\n\\nHer last writing, found in the desk drawer\\nafter her funeral:\\n\\n\",\"style\":{\"font\":\"Permanent Marker\",\"size\":12,\"color\":\"#0b0d14\",\"weight\":\"normal\"}},{\"chars\":\"Architecture isn't space.\\nIt's time.\",\"style\":{\"font\":\"Caveat\",\"size\":22,\"color\":\"#2a2418\",\"weight\":\"bold\",\"italic\":true}}],\"buttons\":null,\"buttonsPerRow\":3}]}}}}");
